/* Rebuilds the two generated files the 3D game loads. You only need this to change the
   3D engine or the character models; the game itself needs no install or build step.

     npm install
     npm run build:3d -- <folder with the downloaded Quaternius packs>

   The folder must hold "Base Characters/Godot - UE/*", "Hairstyles/Rigged to Head Bone/glTF (Godot -Unreal)/*"
   and UAL1_Standard.glb, from https://quaternius.com (see assets/CREDITS.txt).

   js/vendor/three.bundle.js  Three.js as a plain script, because browsers refuse JavaScript
                              modules on a double-clicked file.
   js/vendor/people.data.js   The people and their animations, as text for the same reason. */
import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";
import esbuild from "esbuild";
import sharp from "sharp";
import { NodeIO } from "@gltf-transform/core";
import { ALL_EXTENSIONS } from "@gltf-transform/extensions";
import { dedup, prune, resample, textureCompress } from "@gltf-transform/functions";

const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), "..");
const SRC = process.argv[2];
if (!SRC) throw new Error("Pass the folder with the downloaded model packs.");
const OUT = path.join(ROOT, "js", "vendor");
fs.mkdirSync(OUT, { recursive: true });

// Only the clips the game plays. The originals hold 43.
const CLIPS = ["Idle_Loop", "Idle_Talking_Loop", "Walk_Loop", "Jog_Fwd_Loop", "Sword_Attack", "Interact", "PickUp_Table"];
const HAIR = ["Hair_SimpleParted", "Hair_Buzzed", "Hair_Beard", "Hair_Long", "Hair_Buns"];

await esbuild.build({
  stdin: {
    contents: `
      export * from "three";
      export { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";
      export { clone as cloneSkinned } from "three/examples/jsm/utils/SkeletonUtils.js";
      export { mergeGeometries } from "three/examples/jsm/utils/BufferGeometryUtils.js";`,
    resolveDir: process.cwd()
  },
  bundle: true, minify: true, format: "iife", globalName: "THREE", outfile: path.join(OUT, "three.bundle.js"), legalComments: "inline"
});

const io = new NodeIO().registerExtensions(ALL_EXTENSIONS);
const shrink = (size, slots) => textureCompress({ encoder: sharp, targetFormat: "webp", resize: [size, size], quality: 82, slots });

async function bodyGlb(file) {
  const doc = await io.read(path.join(SRC, "Base Characters", "Godot - UE", file + ".gltf"));
  await doc.transform(dedup(), prune(), shrink(1024, /baseColor/), shrink(512, /normal|metallicRoughness|occlusion/));
  return io.writeBinary(doc);
}

async function hairGlb(file) {
  const doc = await io.read(path.join(SRC, "Hairstyles", "Rigged to Head Bone", "glTF (Godot -Unreal)", file + ".gltf"));
  await doc.transform(dedup(), prune(), shrink(512, /baseColor/), shrink(256, /normal/));
  return io.writeBinary(doc);
}

async function clipsGlb() {
  const doc = await io.read(path.join(SRC, "UAL1_Standard.glb"));
  const root = doc.getRoot();
  root.listAnimations().filter((a) => !CLIPS.includes(a.getName())).forEach((a) => {
    a.listSamplers().forEach((x) => x.dispose());
    a.listChannels().forEach((x) => x.dispose());
    a.dispose();
  });
  root.listMeshes().forEach((m) => m.dispose());
  root.listMaterials().forEach((m) => m.dispose());
  root.listTextures().forEach((t) => t.dispose());
  // Bones only rotate, apart from the hips. Dropping the rest and the redundant keys saves megabytes.
  root.listAnimations().forEach((a) => a.listChannels().forEach((ch) => {
    const name = ch.getTargetNode().getName();
    if (ch.getTargetPath() === "scale" || (ch.getTargetPath() === "translation" && name !== "pelvis" && name !== "root")) {
      ch.getSampler().dispose();
      ch.dispose();
    }
  }));
  await doc.transform(resample({ tolerance: 0.002 }), prune({ keepLeaves: true, keepAttributes: false }));
  // Whatever no animation uses any more, such as the bind matrices of the removed mannequin.
  root.listSkins().forEach((x) => x.dispose());
  root.listAccessors().filter((x) => !x.listParents().some((o) => o !== root)).forEach((x) => x.dispose());
  return io.writeBinary(doc);
}

const data = {
  male: await bodyGlb("Superhero_Male_FullBody"),
  female: await bodyGlb("Superhero_Female_FullBody"),
  clips: await clipsGlb()
};
for (const h of HAIR) data[h] = await hairGlb(h);

const b64 = Object.entries(data).map(([k, v]) => {
  console.log(k.padEnd(20), (v.length / 1024).toFixed(0) + " KB");
  return JSON.stringify(k) + ":" + JSON.stringify(Buffer.from(v).toString("base64"));
});
fs.writeFileSync(path.join(OUT, "people.data.js"), "/* Generated by tools/build-3d-assets.mjs. Models by Quaternius, CC0. */\nCTC.PEOPLE_DATA={" + b64.join(",") + "};\n");
console.log("people.data.js", (fs.statSync(path.join(OUT, "people.data.js")).size / 1048576).toFixed(1) + " MB");
console.log("three.bundle.js", (fs.statSync(path.join(OUT, "three.bundle.js")).size / 1048576).toFixed(2) + " MB");
